/c local p=game.player; if not p then return end; local s=p.surface; local kit={{name="pipe",count=60,quality="normal"},{name="pipe-to-ground",count=48,quality="normal"},{name="fusion-generator",count=24,quality="normal"},{name="cryogenic-plant",count=4,quality="normal"},{name="substation",count=4,quality="normal"},{name="requester-chest",count=4,quality="normal"},{name="inserter",count=4,quality="normal"},{name="fusion-reactor",count=4,quality="normal"}}; local chest_name="passive-provider-chest"; if not prototypes.entity[chest_name] then p.print("Chest unavailable: "..chest_name); return end; for _,it in ipairs(kit) do if not prototypes.item[it.name] then p.print("Item unavailable: "..it.name); return end; if not prototypes.quality[it.quality] then p.print("Quality unavailable: "..it.quality); return end end; local inv=nil; local made=0; local total=0; for _,it in ipairs(kit) do local left=it.count; while left>0 do if not inv then if made>=500 then p.print("Stopped at 500 chests. Inserted "..total.." items; remaining items were not created."); return end; local target={p.position.x+4+(made%10)*2,p.position.y+math.floor(made/10)*2}; local pos=s.find_non_colliding_position(chest_name,target,32,0.5); if not pos then p.print("No clear chest position. Inserted "..total.." items; stopped at "..it.name.." ("..left.." remaining, later items not created)."); return end; local e=s.create_entity{name=chest_name,position=pos,force=p.force,quality="normal",create_build_effect_smoke=false}; if not e then p.print("Chest placement failed after "..total.." items."); return end; made=made+1; inv=e.get_inventory(defines.inventory.chest); if not inv then p.print("Chest has no inventory."); return end end; local empty=inv.is_empty(); local ok,n=pcall(function() return inv.insert{name=it.name,count=left,quality=it.quality} end); if not ok then p.print("Insertion failed for "..it.name..": "..tostring(n)); return end; left=left-n; total=total+n; if left>0 then if n==0 and empty then p.print("Empty chest cannot accept "..it.name..". Stopped after "..total.." items."); return end; inv=nil end end end; p.print("Packed "..total.." items into "..made.." passive-provider-chest. Place them in a powered robot network.")
